-- INSERT INTO "main"."Bot" ("id", "createdAt", "updatedAt", "name", "avatar", "description", "isOfficial") VALUES (1, '2025-03-25 23:55:13', 1742957986296, 'ThumbMaker', 'https://www.myshellstatic.com/cdn-cgi/image/quality=40,format=webp/image/bot/logo/20079665/202409271036/5-cropped-image.png', 'Welcome to ThumbMaker! — Great thumbnails, lots of thumbs up ---  <blockquote>  <b>Default ratio size is Classic.</b>  - Classic(16:9): the classic YouTube thumbnail ratio<br> - Shorts(9:16): the short video thumbnail ratio<br> - Banner(5:2): the homepage banner ratio </blockquote>   ThumbMaker offers three ways to create your creative thumbnails:  - **[🔥Template mode]:** Select a preset template, fill in key details, and quickly generate a professional thumbnail. - **[🌟Freestyle mode]:** Describe your ideas freestyle, and ThumbMaker will create a unique thumbnail image for you.  Choose the mode that suits you best and start crafting your perfect thumbnail!  Or  **Not sure what to put on your thumbnail?** No worries!   **[💬Chat in the input box]**  below the buttons: Just chat with ThumbMaker about your video content or give a quick summary. the agent help you brainstorm some eye-catching ideas for your cover. Let''s get creative together!  If you have a thumbnail that you appreciate, you can also **[🎨upload it as a reference]**.', 0);
